extern "C" int sprintf(char *, const char *, ...);

class entity {};
class kellyslater_controller {};

class stringx
{
  char *chars;
  void *my_buf;
public:
  stringx(const char *, int = -1);
  const char *c_str() const { return chars; }
};

class beach_object
{
  char released_fields[0x38];
public:
  virtual void v00(); virtual void v01(); virtual void v02();
  virtual void v03(); virtual void v04(); virtual void v05();
  virtual void v06(); virtual void v07(); virtual void v08();
  virtual void v09(); virtual void v10(); virtual void v11();
  virtual void v12(); virtual void v13(); virtual void v14();
  virtual void v15(); virtual void v16(); virtual void v17();
  virtual void v18(); virtual void v19(); virtual void v20();
  virtual void v21(); virtual void v22(); virtual void v23();
};

class water_object : public beach_object
{
public:
  virtual int get_type() const { return -1; }
};

class player_info
{
  entity *accomplishments[20];
  int numAccomplishments;
public:
  void AddAccomplishment(entity *);
  int GetNumAccomplishments() const { return numAccomplishments; }
  bool HasAccomplishment(const entity *) const;
};

enum EventType { SS_LAST = 105 };

class IGOFrontEnd
{
public:
  void Print(stringx, EventType = SS_LAST);
};

class FEManager
{
public:
  IGOFrontEnd *IGO;
};

extern player_info current_player_info;
extern stringx ksGlobalTextArray[];
extern FEManager frontendmanager;

class beach
{
  char released_fields[0x2d0];
  entity *smashedEntity;
public:
  beach_object *find_object(entity *) const;
  bool check_smash_challenge(kellyslater_controller *, int, int, int, int);
};

bool beach::check_smash_challenge (kellyslater_controller *ksctrl, int object_type, int object_count, int gt_partially_done, int gt_done)
{
	char display_text[100]; // for printing out messages to the IGO

	if ((smashedEntity != NULL) && (((water_object*)find_object (smashedEntity))->get_type () == object_type))
	{
		if (!current_player_info.HasAccomplishment(smashedEntity))
		{
			current_player_info.AddAccomplishment(smashedEntity);

			if (current_player_info.GetNumAccomplishments() < object_count)
			{
				// Load display_text with something like "1 of 3 tubers", except 
				// appropriate to the current state of things by using the global
				// text array (this also allows for localization)
				sprintf(display_text, ksGlobalTextArray[gt_partially_done].c_str(), current_player_info.GetNumAccomplishments(), object_count);
				frontendmanager.IGO->Print(display_text);
			}
			else if (current_player_info.GetNumAccomplishments() == object_count)
				return true;
		}
	}

	return false;
}
